/**
 * Bible Book 52: 1 தெசலோனிக்கேயர் (1 Thessalonians)
 */
if (typeof window.registerBibleBook === 'function') {
  window.registerBibleBook(52, {"id": 52, "testament": "NT", "code": "1TH", "name_en": "1 Thessalonians", "name_ta": "1 தெசலோனிக்கேயர்", "category": "Pauline Epistles", "category_ta": "பவுலின் நிருபங்கள்", "total_chapters": 5, "chapters": {"1": {"chapter": 1, "duration": 133.95, "audio_url": "audio_nt/B13_01.mp3", "total_verses": 10, "verses": [{"verse": 1, "start": 4.8, "end": 23.12, "ta": "பவுலும், சில்வானும், தீமோத்தேயும், பிதாவாகிய தேவனுக்குள்ளும் கர்த்தராகிய இயேசுகிறிஸ்துவுக்குள்ளும் இருக்கிற தெசலோனிக்கேயர் சபைக்கு எழுதுகிறதாவது: நம்முடைய பிதாவாகிய தேவனாலும் கர்த்தராகிய இயேசுகிறிஸ்துவினாலும் உங்களுக்குக் கிருபையும் சமாதானமும் உண்டாவதாக.", "en": "Paul, and Silvanus, and Timotheus, unto the church of the Thessalonians which is in God the Father and in the Lord Jesus Christ: Grace be unto you, and peace, from God our Father, and the Lord Jesus Christ."}, {"verse": 2, "start": 23.12, "end": 40.77, "ta": "தேவனுக்குப் பிரியமான சகோதரரே, உங்கள் விசுவாசத்தின் கிரியையையும், உங்கள் அன்பின் பிரயாசத்தையும், நம்முடைய கர்த்தருடைய இயேசுகிறிஸ்துவின்மேலுள்ள உங்கள் நம்பிக்கையின் பொறுமையையும், நம்முடைய பிதாவாகிய தேவனுக்குமுன்பாக நாங்கள் இடைவிடாமல் நினைவுகூர்ந்து,", "en": "We give thanks to God always for you all, making mention of you in our prayers;"}, {"verse": 3, "start": 40.77, "end": 44.61, "ta": "நீங்கள் தெரிந்துகொள்ளப்பட்டவர்களென்று நாங்கள் அறிந்து,", "en": "Remembering without ceasing your work of faith, and labour of love, and patience of hope in our Lord Jesus Christ, in the sight of God and our Father;"}, {"verse": 4, "start": 44.61, "end": 53.64, "ta": "எங்கள் ஜெபங்களில் இடைவிடாமல் உங்களைக்குறித்து விண்ணப்பம்பண்ணி, உங்களெல்லாருக்காகவும் எப்பொழுதும் தேவனை ஸ்தோத்திரிக்கிறோம்.", "en": "Knowing, brethren beloved, your election of God."}, {"verse": 5, "start": 53.64, "end": 70.07, "ta": "எங்கள் சுவிசேஷம் உங்களிடத்தில் வசனத்தோடேமாத்திரமல்ல, வல்லமையோடும், பரிசுத்த ஆவியோடும், முழுநிச்சயத்தோடும் வந்தது; நாங்களும் உங்களுக்குள்ளே இருந்தபோது உங்கள்நிமித்தம் எப்படிப்பட்டவர்களாயிருந்தோமென்று அறிந்திருக்கிறீர்களே.", "en": "For our gospel came not unto you in word only, but also in power, and in the Holy Ghost, and in much assurance; as ye know what manner of men we were among you for your sake."}, {"verse": 6, "start": 70.07, "end": 79.98, "ta": "நீங்கள் மிகுந்த உபத்திரவத்திலே, பரிசுத்த ஆவியின் சந்தோஷத்தோடே, தοருவசனத்தை ஏற்றுக்கொண்டு, எங்களையும் கர்த்தரையும் பின்பற்றுகிறவர்களாகி,", "en": "And ye became followers of us, and of the Lord, having received the word in much affliction, with joy of the Holy Ghost:"}, {"verse": 7, "start": 79.98, "end": 86.31, "ta": "இவ்விதமாய் மக்கெதோனியாவிலும் அகாயாவிலுமுள்ள விசுவாசிகள் யாவருக்கும் மாதிரிகளானீர்கள்.", "en": "So that ye were ensamples to all that believe in Macedonia and Achaia."}, {"verse": 8, "start": 86.31, "end": 102.0, "ta": "எப்படியெனில், உங்களிடத்திலிருந்து கர்த்தருடைய வசனம் மக்கெதோனியாவிலும் அகாயாவிலும் தொனித்ததுமல்லாமல், நாங்கள் அதைக்குறித்து ஒன்றும் சொல்லவேண்டியதாயிராதபடிக்கு, தேவனைப்பற்றின உங்கள் விசுவாசம் எங்கும் பிரசித்தமாயிற்று.", "en": "For from you sounded out the word of the Lord not only in Macedonia and Achaia, but also in every place your faith to God-ward is spread abroad; so that we need not to speak any thing."}, {"verse": 9, "start": 102.0, "end": 116.69, "ta": "ஏனெனில், அவர்கள்தாமே எங்களைக்குறித்து, உங்களிடத்தில் நாங்கள் அடைந்த பிரவேசம் இன்னதென்பதையும், ஜீவனுள்ள மெய்யான தேவனுக்கு ஊழியஞ்செய்வதற்கு, நீங்கள் விக்கிரகங்களை விட்டு தேவனிடத்திற்கு மனந்திரும்பினதையும்,", "en": "For they themselves shew of us what manner of entering in we had unto you, and how ye turned to God from idols to serve the living and true God;"}, {"verse": 10, "start": 116.69, "end": 132.45, "ta": "அவர் மரித்தோரிலிருந்தெழுப்பினவரும், இனிவரும் கோபாக்கினையினின்று நம்மை நீங்கலாக்கி இரட்சிக்கிறவருமாயிருக்கிற அவருடைய குமாரனாகிய இயேசு பரலோகத்திலிருந்து வருவதை நீங்கள் எதிர்பார்த்துக்கொண்டிருக்கிறதையும், அறிவிக்கிறார்களே.", "en": "And to wait for his Son from heaven, whom he raised from the dead, even Jesus, which delivered us from the wrath to come."}]}, "2": {"chapter": 2, "duration": 239.5, "audio_url": "audio_nt/B13_02.mp3", "total_verses": 20, "verses": [{"verse": 1, "start": 3.8, "end": 11.13, "ta": "சகோதரரே, நாங்கள் உங்களிடத்தில் பிரவேசித்தது வீணாயிருக்கவில்லையென்று நீங்களே அறிந்திருக்கிறீர்கள்.", "en": "For yourselves, brethren, know our entrance in unto you, that it was not in vain:"}, {"verse": 2, "start": 11.13, "end": 26.45, "ta": "உங்களுக்குத் தெரிந்திருக்கிறபடி, முன்னே பிலிப்பிபட்டணத்திலே நாங்கள் பாடுபட்டு நிந்தையடைந்திருந்தும், வெகு போராட்டத்தோடே தேவனுடைய சுவிசேஷத்தை உங்களுக்குச் சொல்லும்படி, நம்முடைய தேவனுக்குள் தைரியங்கொண்டிருந்தோம்.", "en": "But even after that we had suffered before, and were shamefully entreated, as ye know, at Philippi, we were bold in our God to speak unto you the gospel of God with much contention."}, {"verse": 3, "start": 26.45, "end": 33.24, "ta": "எங்கள் போதகம் வஞ்சகத்தினாலும் துராசையினாலும் உண்டாகவில்லை, அது கபடமுள்ளதாயுமிருக்கவில்லை.", "en": "For our exhortation was not of deceit, nor of uncleanness, nor in guile:"}, {"verse": 4, "start": 33.24, "end": 46.42, "ta": "சுவிசேஷத்தை எங்களிடத்தில் ஒப்புவிக்கத்தக்கதாய், தேவன் எங்களை உத்தமரென்றெண்ணினபடியே, நாங்கள் மனுஷருக்கு அல்ல, எங்கள் இருதயங்களைச் சோதித்தறிகிற தேவனுக்கே பிரியமுண்டாகப் பேசுகிறோம்.", "en": "But as we were allowed of God to be put in trust with the gospel, even so we speak; not as pleasing men, but God, which trieth our hearts."}, {"verse": 5, "start": 46.42, "end": 57.38, "ta": "உங்களுக்குத் தெரிந்திருக்கிறபடி, நாங்கள் ஒருக்காலும் இச்சகமான வசனங்களைச் சொல்லவுமில்லை, பொருளாசையுள்ளவர்களாய் மாயம்பண்ணவுமில்லை; தேவனே சாட்சி.", "en": "For neither at any time used we flattering words, as ye know, nor a cloke of covetousness; God is witness:"}, {"verse": 6, "start": 57.38, "end": 69.41, "ta": "நாங்கள் கிறிஸ்துவின் அப்போஸ்தலராக உங்களுக்குப் பாரமாயிருக்கக்கூடியவர்களானாலும், உங்களிடத்திலாவது, மற்றவர்களிடத்திலாவது, மனுஷரால் வரும் மகிமையை நாங்கள் தேடவில்லை.", "en": "Nor of men sought we glory, neither of you, nor yet of others, when we might have been burdensome, as the apostles of Christ."}, {"verse": 7, "start": 69.41, "end": 76.6, "ta": "உங்களிடத்தில் பட்சமாய் நடந்துகொண்டோம்; பால் கொடுக்கிற தாயானவள் தன் பிள்ளைகளைக் காப்பாற்றுகிறதுபோல,", "en": "But we were gentle among you, even as a nurse cherisheth her children:"}, {"verse": 8, "start": 76.6, "end": 90.58, "ta": "நாங்கள் உங்கள்மேல் வாஞ்சையாயிருந்து, தேவனுடைய சுவிசேஷத்தை உங்களுக்குக் கொடுத்ததுமல்லாமல், நீங்கள் எங்களுக்குப் பிரியமானவர்களானபடியினாலே, எங்கள் ஜீவனையும் உங்களுக்குக் கொடுக்க மனதாயிருந்தோம்.", "en": "So being affectionately desirous of you, we were willing to have imparted unto you, not the gospel of God only, but also our own souls, because ye were dear unto us."}, {"verse": 9, "start": 90.58, "end": 105.51, "ta": "சகோதரரே, நாங்கள் பட்ட பிரயாசமும் வருத்தமும் உங்களுக்கு ஞாபகமாயிருக்கும்; உங்களில் ஒருவனுக்கும் பாரமாயிராதபடிக்கு, இரவும் பகலும் நாங்கள் வேலைசெய்து, தேவனுடைய சுவிசேஷத்தை உங்களிடத்தில் பிரசங்சித்தோம்.", "en": "For ye remember, brethren, our labour and travail: for labouring night and day, because we would not be chargeable unto any of you, we preached unto you the gospel of God."}, {"verse": 10, "start": 105.51, "end": 115.39, "ta": "விசுவாசிகளாகிய உங்களுக்குள்ளே நாங்கள் எவ்வளவு பரிசுத்தமும் நீதியும் பிழையின்மையுமாய் நடந்தோமென்பதற்கு நீங்களும் சாட்சி, தேவனும் சாட்சி.", "en": "Ye are witnesses, and God also , how holily and justly and unblameably we behaved ourselves among you that believe:"}, {"verse": 11, "start": 115.39, "end": 122.98, "ta": "மேலும், தம்முடைய ராஜ்யத்திற்கும் மகிமைக்கும் உங்களை அழைத்த தேவனுக்கு நீங்கள் பாத்திரராய் நடக்கவேண்டுமென்று,", "en": "As ye know how we exhorted and comforted and charged every one of you, as a father doth his children,"}, {"verse": 12, "start": 122.98, "end": 133.27, "ta": "தகப்பன் தன் பிள்ளைகளுக்குச் சொல்லுகிறதுபோல, நாங்கள் உங்களில் ஒவ்வொருவனுக்கும் புத்தியும் தேறுதலும் எச்சரிப்பும் சொன்னதை அறிந்திருக்கிறீர்கள்.", "en": "That ye would walk worthy of God, who hath called you unto his kingdom and glory."}, {"verse": 13, "start": 133.27, "end": 153.3, "ta": "ஆகையால், நீங்கள் தேவவசனத்தை எங்களாலே கேள்விப்பட்டு ஏற்றுக்கொண்டபோது, அதை மனுஷர் வசனமாக ஏற்றுக்கொள்ளாமல், தேவவசனமாகவே ஏற்றுக்கொண்டதினாலே நாங்கள் இடைவிடாமல் தேவனுக்கு ஸ்தோத்திரஞ்செலுத்துகிறோம்; அது மெய்யாகவே தேவவசனந்தான், விசுவாசிக்கிற உங்களுக்குள்ளே அது பெலனும் செய்கிறது.", "en": "For this cause also thank we God without ceasing, because, when ye received the word of God which ye heard of us, ye received it not as the word of men, but as it is in truth, the word of God, which effectually worketh also in you that believe."}, {"verse": 14, "start": 153.3, "end": 168.56, "ta": "எப்படியெனில், சகோதரரே, யூதேயா தேசத்தில் கிறிஸ்து இயேசுவுக்குள்ளான தேவனுடைய சபைகளை நீங்கள் பின்பற்றினவர்களாகி, அவர்கள் யூதராலே எப்படிப் பாடுபட்டார்களோ, அப்படியே நீங்களும் உங்கள் சுய ஜனங்களாலே பாடுபட்டீர்கள்.", "en": "For ye, brethren, became followers of the churches of God which in Judaea are in Christ Jesus: for ye also have suffered like things of your own countrymen, even as they have of the Jews:"}, {"verse": 15, "start": 168.56, "end": 181.8, "ta": "அந்த யூதர்கள் கர்த்தராகிய இயேசுவையும், தங்கள் தீர்க்கதரிசிகளையும் கொலைசெய்தவர்களும், எங்களைத் துன்பப்படுத்தினவர்களும், தேவனுக்கேற்காதவர்களும், மனுஷர் யாவருக்கும் விரோதிகளுமாயிருந்து,", "en": "Who both killed the Lord Jesus, and their own prophets, and have persecuted us; and they please not God, and are contrary to all men:"}, {"verse": 16, "start": 181.8, "end": 196.32, "ta": "புறஜாதியார் இரட்சிக்கப்படுவதற்கு நாங்கள் அவர்களோடே பேசாதபடிக்குத் தடைபண்ணுகிறார்கள்; இவ்விதமாய் எக்காலத்திலும் தங்கள் பாவங்களை நிறைவாக்குகிறார்கள்; அவர்கள்மேல் கோபாக்கினை பூரணமாய் வந்திருக்கிறது.", "en": "Forbidding us to speak to the Gentiles that they might be saved, to fill up their sins alway: for the wrath is come upon them to the uttermost."}, {"verse": 17, "start": 196.32, "end": 210.78, "ta": "சகோதரரே, நாங்கள் இருதயத்தின்படி உங்களோடிருந்து, சரீரத்தின்படி கொஞ்சக்காலம் உங்களைவிட்டுப் பிரிந்திருந்தபடியினாலே, உங்கள் முகத்தைப்பார்க்கவேண்டுமென்று மிகுந்த ஆசையோடே அதிகமாய்ப் பிரயத்தனம்பண்ணினோம்.", "en": "But we, brethren, being taken from you for a short time in presence, not in heart, endeavoured the more abundantly to see your face with great desire."}, {"verse": 18, "start": 210.78, "end": 220.66, "ta": "ஆகையால், நாங்கள் உங்களிடத்தில்வர இரண்டொருதரம் மனதாயிருந்தோம், பவுலாகிய நானே வர மனதாயிருந்தேன்; சாத்தானோ எங்களைத் தடைபண்ணினான்.", "en": "Wherefore we would have come unto you, even I Paul, once and again; but Satan hindered us."}, {"verse": 19, "start": 220.66, "end": 233.7, "ta": "எங்களுக்கு நம்பிக்கையும் சந்தோஷமும் மகிழ்ச்சியின் கிரீடமுமாயிருப்பவர்கள் யார்? நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்து வரும்போது அவருடைய சந்நிதானத்திலே நீங்களல்லவா அப்படியிருப்பீர்கள்;", "en": "For what is our hope, or joy, or crown of rejoicing? Are not even ye in the presence of our Lord Jesus Christ at his coming?"}, {"verse": 20, "start": 233.7, "end": 238.0, "ta": "நீங்களே எங்களுக்கு மகிமையும் சந்தோஷமுமாயிருக்கிறீர்கள்.", "en": "For ye are our glory and joy."}]}, "3": {"chapter": 3, "duration": 149.32, "audio_url": "audio_nt/B13_03.mp3", "total_verses": 13, "verses": [{"verse": 1, "start": 3.8, "end": 11.41, "ta": "ஆகையால், நாங்கள் இனிப் பொறுத்திருக்கக்கூடாமல், அத்தேனே பட்டணத்தில் தனித்துவிடப்படுகிறது நன்மையென்று நினைத்து,", "en": "Wherefore when we could no longer forbear, we thought it good to be left at Athens alone;"}, {"verse": 2, "start": 11.41, "end": 28.37, "ta": "இந்த உபத்திரவங்களினாலே ஒருவனும் அசைக்கப்படாதபடிக்கு உங்களைத் திடப்படுத்தவும், உங்கள் விசுவாசத்தைப்பற்றி உங்களுக்குப் புத்திசொல்லவும், நம்முடைய சகோதரனும் தேவ ஊழியக்காரனும் கிறிஸ்துவின் சுவிசேஷத்தில் எங்கள் உடன்வேலையாளுமாகிய தீமோத்தேயுவை அனுப்பினோம்.", "en": "And sent Timotheus, our brother, and minister of God, and our fellowlabourer in the gospel of Christ, to establish you, and to comfort you concerning your faith:"}, {"verse": 3, "start": 28.37, "end": 35.4, "ta": "இப்படிப்பட்ட உபத்திரவங்களைச் சகிக்க நாம் நியமிக்கப்பட்டிருக்கிறோமென்று நீங்கள் அறிந்திருக்கிறீர்களே.", "en": "That no man should be moved by these afflictions: for yourselves know that we are appointed thereunto."}, {"verse": 4, "start": 35.4, "end": 45.59, "ta": "நமக்கு உபத்திரவம் வருமென்று நாங்கள் உங்களிடத்திலிருந்தபோது, உங்களுக்கு முன்னறிவித்தோம்; அப்படியே வந்து நேரிட்டதென்றும் அறிந்திருக்கிறீர்கள்.", "en": "For verily, when we were with you, we told you before that we should suffer tribulation; even as it came to pass, and ye know."}, {"verse": 5, "start": 45.59, "end": 59.01, "ta": "ஆகையால், நான் இனிப் பொறுத்திருக்கக்கூடாமல், எங்கள் வேலை வீணாய்ப் போகத்தக்கதாகச் சோதனைக்காரன் உங்களைச் சோதனைக்குட்படுத்தினதுண்டோவென்று, உங்கள் விசுவாசத்தை அறியும்படிக்கு, அவனை அனுப்பினேன்.", "en": "For this cause, when I could no longer forbear, I sent to know your faith, lest by some means the tempter have tempted you, and our labour be in vain."}, {"verse": 6, "start": 59.01, "end": 79.58, "ta": "இப்பொழுது தீமோத்தேயு உங்களிடத்திலிருந்து எங்களிடத்தில் வந்து, உங்கள் விசுவாசத்தையும் அன்பையும் குறித்தும், நீங்கள் எப்பொழுதும் எங்களைப் பட்சமாய் நினைத்துக்கொண்டு, நாங்கள் உங்களைக் காண வாஞ்சையாயிருக்கிறதுபோல நீங்களும் எங்களைக் காண வாஞ்சையாயிருக்கிறீர்களென்பதைக்குறித்தும், எங்களுக்கு நற்செய்திசொன்னதினாலே,", "en": "But now when Timotheus came from you unto us, and brought us good tidings of your faith and charity, and that ye have good remembrance of us always, desiring greatly to see us, as we also to see you:"}, {"verse": 7, "start": 79.58, "end": 87.9, "ta": "சகோதரரே, எங்களுக்கு நேரிட்ட எல்லா இக்கட்டிலும் உபத்திரவத்திலும் உங்கள் விசுவாசத்தினாலே உங்களை குறித்து ஆறுதலடைந்தோம்.", "en": "Therefore, brethren, we were comforted over you in all our affliction and distress by your faith:"}, {"verse": 8, "start": 87.9, "end": 92.68, "ta": "நீங்கள் கர்த்தருக்குள் நிலைத்திருந்தால் நாங்கள் பிழைத்திருப்போம்.", "en": "For now we live, if ye stand fast in the Lord."}, {"verse": 9, "start": 92.68, "end": 103.58, "ta": "மேலும், நம்முடைய தேவனுக்கு முன்பாக நாங்கள் உங்களைக்குறித்து அடைந்திருக்கிற மிகுந்த சந்தோஷத்திற்காக, நாங்கள் தேவனுக்கு எவ்விதமாய் ஸ்தோத்திரம் செலுத்துவோம்?", "en": "For what thanks can we render to God again for you, for all the joy wherewith we joy for your sakes before our God;"}, {"verse": 10, "start": 103.58, "end": 112.15, "ta": "உங்கள் முகத்தைக் கண்டு, உங்கள் விசுவாசத்தின் குறைவுகளை நிறைவாக்கும்பொருட்டு, இரவும் பகலும் மிகவும் வேண்டிக்கொள்கிறோமே.", "en": "Night and day praying exceedingly that we might see your face, and might perfect that which is lacking in your faith?"}, {"verse": 11, "start": 112.15, "end": 119.83, "ta": "நம்முடைய பிதாவாகிய தேவனும் நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவும் உங்களிடத்திற்கு எங்களை நேராக வழிநடத்துவாராக.", "en": "Now God himself and our Father, and our Lord Jesus Christ, direct our way unto you."}, {"verse": 12, "start": 119.83, "end": 132.92, "ta": "நாங்கள் உங்களிடத்தில் வைத்திருக்கிற அன்புக்கொப்பாய், நீங்களும் ஒருவரிடத்தில் ஒருவர் வைக்கும் அன்பிலும் மற்றெல்லா மனுஷரிடத்தில் வைக்கும் அன்பிலும் கர்த்தர் உங்களைப் பெருகவும் நிலைத்தோங்கவும் செய்து,", "en": "And the Lord make you to increase and abound in love one toward another, and toward all men , even as we do toward you:"}, {"verse": 13, "start": 132.92, "end": 147.82, "ta": "இவ்விதமாய் நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்து தமது பரிசுத்தவான்கள் அனைவரோடுங்கூட வரும்போது, நீங்கள் நம்முடைய பிதாவாகிய தேவனுக்கு முன்பாகப் பிழையற்ற பரிசுத்தமுள்ளவர்களாயிருக்கும்படி உங்கள் இருதயங்களை ஸ்திரப்படுத்துவாராக.", "en": "To the end he may stablish your hearts unblameable in holiness before God, even our Father, at the coming of our Lord Jesus Christ with all his saints."}]}, "4": {"chapter": 4, "duration": 173.77, "audio_url": "audio_nt/B13_04.mp3", "total_verses": 18, "verses": [{"verse": 1, "start": 3.8, "end": 20.82, "ta": "அன்றியும், சகோதரரே, நீங்கள் இன்னின்ன பிரகாரமாய் நடக்கவும், தேவனுக்குப் பிரியமாயிருக்கவும் வேண்டுமென்று, நீங்கள் எங்களால் கேட்டு ஏற்றுக்கொண்டபடியே, அதிகமதிகமாய்த் தேறும்படிக்கு, கர்த்தராகிய இயேசுவுக்குள் உங்களை வேண்டிக்கொண்டு புத்திசொல்லுகிறோம்.", "en": "Furthermore then we beseech you, brethren, and exhort you by the Lord Jesus, that as ye have received of us how ye ought to walk and to please God, so ye would abound more and more."}, {"verse": 2, "start": 20.82, "end": 26.66, "ta": "கர்த்தராகிய இயேசுவினாலே நாங்கள் உங்களுக்குக் கொடுத்த கட்டளைகளை அறிந்திருக்கிறீர்களே.", "en": "For ye know what commandments we gave you by the Lord Jesus."}, {"verse": 3, "start": 26.66, "end": 35.4, "ta": "நீங்கள் பரிசுத்தமுள்ளவர்களாகவேண்டுமென்பதே தேவனுடைய சித்தமாயிருக்கிறது. அந்தப்படி, நீங்கள் வேசிமார்க்கத்துக்கு விலகியிருந்து,", "en": "For this is the will of God, even your sanctification, that ye should abstain from fornication:"}, {"verse": 4, "start": 35.4, "end": 38.79, "ta": "தேவனை அறியாத அஞ்ஞானிகளைப்போல மோக இச்சைக்குட்படாமல்,", "en": "That every one of you should know how to possess his vessel in sanctification and honour;"}, {"verse": 5, "start": 38.79, "end": 44.32, "ta": "உங்களில் அவனவன் தன்தன் சரீரபாண்டத்தைப் பரிசுத்தமாயும் கனமாயும் ஆண்டுகொள்ளும்படி அறிந்து:", "en": "Not in the lust of concupiscence, even as the Gentiles which know not God:"}, {"verse": 6, "start": 44.32, "end": 59.96, "ta": "இந்த விஷயத்தில் ஒருவனும் மீறாமலும் தன் சகோதரனை வஞ்சியாமலும் இருக்கவேண்டும்; முன்னமே நாங்கள் உங்களுக்குச் சொல்லி, சாட்சியாக எச்சரித்தபடியே இப்படிப்பட்ட விஷயங்களெல்லாவற்றையுங்குறித்துக் கர்த்தர் நீதியைச் சரிக்கட்டுகிறவராயிருக்கிறார்.", "en": "That no man go beyond and defraud his brother in any matter: because that the Lord is the avenger of all such, as we also have forewarned you and testified."}, {"verse": 7, "start": 59.96, "end": 64.54, "ta": "தேவன் நம்மை அசுத்தத்திற்கல்ல பரிசுத்தத்திற்கே அழைத்திருக்கிறார்.", "en": "For God hath not called us unto uncleanness, but unto holiness."}, {"verse": 8, "start": 64.54, "end": 71.58, "ta": "ஆகையால் அசட்டைபண்ணுகிறவன் மனுஷரை அல்ல தமது பரிசுத்த ஆவியை நமக்குத் தந்தருளின தேவனையே அசட்டைபண்ணுகிறான்.", "en": "He therefore that despiseth, despiseth not man, but God, who hath also given unto us his holy Spirit."}, {"verse": 9, "start": 71.58, "end": 81.88, "ta": "சகோதர சிநேகத்தைக்குறித்து நான் உங்களுக்கு எழுதவேண்டுவதில்லை; நீங்கள் ஒருவரிலொருவர் அன்பாயிருக்கும்படிக்கு தேவனால் போதிக்கப்பட்டவர்களாயிருக்கிறீர்களே.", "en": "But as touching brotherly love ye need not that I write unto you: for ye yourselves are taught of God to love one another."}, {"verse": 10, "start": 81.88, "end": 91.68, "ta": "அந்தப்படி நீங்கள் மக்கெதோனியா நாடெங்குமுள்ள சகோதரரெல்லாருக்கும் செய்துவருகிறீர்கள். சகோதரரே, அன்பிலே நீங்கள் இன்னும் அதிகமாய்ப் பெருகவும்;", "en": "And indeed ye do it toward all the brethren which are in all Macedonia: but we beseech you, brethren, that ye increase more and more;"}, {"verse": 11, "start": 91.68, "end": 98.4, "ta": "புறம்பேயிருக்கிறவர்களைப்பற்றி யோக்கியமாய் நடந்து, ஒன்றிலும் உங்களுக்குக் குறைவில்லாதிருக்கும்படிக்கு,", "en": "And that ye study to be quiet, and to do your own business, and to work with your own hands, as we commanded you;"}, {"verse": 12, "start": 98.4, "end": 112.03, "ta": "நாங்கள் உங்களுக்குக் கட்டளையிட்டபடியே, அமைதலுள்ளவர்களாயிருக்கும்படி நாடவும், உங்கள் சொந்த அலுவல்களைப் பார்க்கவும், உங்கள் சொந்தக் கைகளினாலே வேலைசெய்யவும் வேண்டுமென்று உங்களுக்குப் புத்திசொல்லுகிறோம்.", "en": "That ye may walk honestly toward them that are without, and that ye may have lack of nothing."}, {"verse": 13, "start": 112.03, "end": 122.14, "ta": "அன்றியும், சகோதரரே, நித்திரையடைந்தவர்களினிமித்தம் நீங்கள் நம்பிக்கையற்றவர்களான மற்றவர்களைப் போலத் துக்கித்து, அறிவில்லாதிருக்க எனக்கு மனதில்லை.", "en": "But I would not have you to be ignorant, brethren, concerning them which are asleep, that ye sorrow not, even as others which have no hope."}, {"verse": 14, "start": 122.14, "end": 132.19, "ta": "இயேசுவானவர் மரித்து பின்பு எழுந்திருந்தாரென்று விசுவாசிக்கிறோமே; அப்படியே இயேசுவுக்குள் நித்திரையடைந்தவர்களையும் தேவன் அவரோடேகூடக் கொண்டுவருவார்.", "en": "For if we believe that Jesus died and rose again, even so them also which sleep in Jesus will God bring with him."}, {"verse": 15, "start": 132.19, "end": 142.94, "ta": "கர்த்தருடைய வார்த்தையை முன்னிட்டு நாங்கள் உங்களுக்குச் சொல்லுகிறதாவது: கர்த்தருடைய வருகைமட்டும் உயிரோடிருக்கும் நாம் நித்திரையடைந்தவர்களுக்கு முந்திக்கொள்வதில்லை.", "en": "For this we say unto you by the word of the Lord, that we which are alive and remain unto the coming of the Lord shall not prevent them which are asleep."}, {"verse": 16, "start": 142.94, "end": 156.06, "ta": "ஏனெனில், கர்த்தர் தாமே ஆரவாத்தோடும், பிரதான தூதனுடைய சத்தத்தோடும், தேவ எக்காளத்தோடும் வானத்திலிருந்து இறங்கிவருவார்; அப்பொழுது கிறிஸ்துவுக்குள் மரித்தவர்கள் முதலாவது எழுந்திருப்பார்கள்.", "en": "For the Lord himself shall descend from heaven with a shout, with the voice of the archangel, and with the trump of God: and the dead in Christ shall rise first:"}, {"verse": 17, "start": 156.06, "end": 167.5, "ta": "பின்பு உயிரோடிருக்கும் நாமும் கர்த்தருக்கு எதிர்கொண்டுபோக மேகங்கள்மேல், அவர்களோடேகூட ஆகாயத்தில் எடுத்துக்கொள்ளப்பட்டு, இவ்விதமாய் எப்பொழுதும் கர்த்தருடனேகூட இருப்போம்.", "en": "Then we which are alive and remain shall be caught up together with them in the clouds, to meet the Lord in the air: and so shall we ever be with the Lord."}, {"verse": 18, "start": 167.5, "end": 172.27, "ta": "ஆகையால், இந்த வார்த்தைகளினாலே நீங்கள் ஒருவரையொருவர் தேற்றுங்கள்.", "en": "Wherefore comfort one another with these words."}]}, "5": {"chapter": 5, "duration": 211.14, "audio_url": "audio_nt/B13_05.mp3", "total_verses": 28, "verses": [{"verse": 1, "start": 3.8, "end": 9.88, "ta": "சகோதரரே இவைகள் நடக்குங்காலங்களையும் சமயங்களையுங்குறித்து உங்களுக்கு எழுதவேண்டுவதில்லை.", "en": "But of the times and the seasons, brethren, ye have no need that I write unto you."}, {"verse": 2, "start": 9.88, "end": 16.54, "ta": "இரவிலே திருடன் வருகிறவிதமாய்க் கர்த்தருடைய நாள் வருமென்று நீங்களே நன்றாய் அறிந்திருக்கிறீர்கள்.", "en": "For yourselves know perfectly that the day of the Lord so cometh as a thief in the night."}, {"verse": 3, "start": 16.54, "end": 27.82, "ta": "சமாதானமும் சவுக்கியமும் உண்டென்று அவர்கள் சொல்லும்போது, கர்ப்பவதியானவளுக்கு வேதனை வருகிறதுபோல, அழிவு சடிதியாய் அவர்கள்மேல் வரும்; அவர்கள் தப்பிப்போவதில்லை.", "en": "For when they shall say, Peace and safety; then sudden destruction cometh upon them, as travail upon a woman with child; and they shall not escape."}, {"verse": 4, "start": 27.82, "end": 35.31, "ta": "சகோதரரே, அந்த நாள் திருடனைப்போல உங்களைப் பிடித்துக்கொள்ளத்தக்கதாக நீங்கள் அந்தகாரத்திலிருக்கிறவர்களல்லவே.", "en": "But ye, brethren, are not in darkness, that that day should overtake you as a thief."}, {"verse": 5, "start": 35.31, "end": 44.53, "ta": "நீங்களெல்லாரும் வெளிச்சத்தின் பிள்ளைகளும், பகலின் பிள்ளைகளுமாயிருக்கிறீர்கள்; நாம் இயேசுவுக்கும் இருளுக்கும் உள்ளானவர்களல்லவே.", "en": "Ye are all the children of light, and the children of the day: we are not of the night, nor of darkness."}, {"verse": 6, "start": 44.53, "end": 51.71, "ta": "ஆகையால், மற்றவர்கள் தூங்குகிறதுபோல நாம் தூங்காமல், விழித்துக்கொண்டு தெளிந்தவர்களாயிருக்கக்கடவோம்.", "en": "Therefore let us not sleep, as do others; but let us watch and be sober."}, {"verse": 7, "start": 51.71, "end": 58.88, "ta": "தூங்குகிறவர்கள் இராத்திரியிலே தூங்குவார்கள்; வெறிகொள்ளுகிறவர்கள் இராத்திரியிலே வெறிகொள்ளுவார்கள்.", "en": "For they that sleep sleep in the night; and they that be drunken are drunken in the night."}, {"verse": 8, "start": 58.88, "end": 70.6, "ta": "பகலுக்குரியவர்களாகிய நாமோ தெளிந்தவர்களாயிருந்து, விசுவாசம் அன்பு என்னும் மார்க்கவசத்தையும், இரட்சிப்பின் நம்பிக்கையென்னும் தலைச்சீராவையும் தரித்துக்கொண்டிருக்கக்கடவாம்.", "en": "But let us, who are of the day, be sober, putting on the breastplate of faith and love; and for an helmet, the hope of salvation."}, {"verse": 9, "start": 70.6, "end": 79.24, "ta": "தேவன் நம்மைக் கோபாக்கினைக்கென்று நியமிக்காமல், நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துமூலமாய் இரட்சிப்படைவதற்கென்று நியமித்தார்.", "en": "For God hath not appointed us to wrath, but to obtain salvation by our Lord Jesus Christ,"}, {"verse": 10, "start": 79.24, "end": 88.21, "ta": "நாம் விழித்திருப்பவர்களானாலும் நித்திரையடைந்தவர்களானாலும், தம்முடனேகூட நாம் ஏகமாய்ப் பிழைத்திருக்கும்படி அவர் நமக்காக மரித்தாரே.", "en": "Who died for us, that, whether we wake or sleep, we should live together with him."}, {"verse": 11, "start": 88.21, "end": 96.34, "ta": "ஆகையால் நீங்கள் செய்துவருகிறபடியே, ஒருவரையொருவர் தேற்றி, ஒருவருக்கொருவர் பக்திவிருத்தி உண்டாகும்படி செய்யுங்கள்.", "en": "Wherefore comfort yourselves together, and edify one another, even as also ye do."}, {"verse": 12, "start": 96.34, "end": 107.1, "ta": "அன்றியும், சகோதரரே, உங்களுக்குள்ளே பிரயாசப்பட்டு, கர்த்தருக்குள் உங்களை விசாரணைசெய்கிறவர்களாயிருந்து, எங்களுக்குப் புத்திசொல்லுகிறவர்களை நீங்கள் மதித்து,", "en": "And we beseech you, brethren, to know them which labour among you, and are over you in the Lord, and admonish you;"}, {"verse": 13, "start": 107.1, "end": 116.84, "ta": "அவர்களுடைய கிரியையினிமித்தம் அவர்களை மிகவும் அன்பாய் எண்ணிக்கொள்ளும்படி உங்களை வேண்டிக்கொள்ளுகிறோம். உங்களுக்குள்ளே சமாதானமாயிருங்கள்.", "en": "And to esteem them very highly in love for their work’s sake. And be at peace among yourselves."}, {"verse": 14, "start": 116.84, "end": 131.25, "ta": "மேலும், சகோதரரே, நாங்கள் உங்களுக்குப் போதிக்கிறதென்னவென்றால், ஒழுங்கில்லாதவர்களுக்குப் புத்திசொல்லுங்கள், திடனற்றவர்களைத் தேற்றுங்கள், பலவீனரைத் தாங்குங்கள், எல்லாரிடத்திலும் நீடிய சாந்தமாயிருங்கள்.", "en": "Now we exhort you, brethren, warn them that are unruly, comfort the feebleminded, support the weak, be patient toward all men ."}, {"verse": 15, "start": 131.25, "end": 140.98, "ta": "ஒருவனும் மற்றொருவன் செய்யும் தீமைக்குத் தீமைசெய்யாதபடி பாருங்கள்; உங்களுக்குள்ளும் மற்ற யாவருக்குள்ளும் எப்பொழுதும் நன்மைசெய்ய நாடுங்கள்.", "en": "See that none render evil for evil unto any man ; but ever follow that which is good, both among yourselves, and to all men ."}, {"verse": 16, "start": 140.98, "end": 143.48, "ta": "எப்பொழுதும் சந்தோஷமாயிருங்கள்.", "en": "Rejoice evermore."}, {"verse": 17, "start": 143.48, "end": 145.79, "ta": "இடைவிடாமல் ஜெபம்பண்ணுங்கள்.", "en": "Pray without ceasing."}, {"verse": 18, "start": 145.79, "end": 154.95, "ta": "எல்லாவற்றிலேயும் ஸ்தோத்திரஞ்செய்யுங்கள்; அப்படிச் செய்வதே கிறிஸ்து இயேசுவுக்குள் உங்களைக்குறித்துத் தேவனுடைய சித்தமாயிருக்கிறது.", "en": "In every thing give thanks: for this is the will of God in Christ Jesus concerning you."}, {"verse": 19, "start": 154.95, "end": 157.38, "ta": "ஆவியை அவித்துப்போடாதிருங்கள்.", "en": "Quench not the Spirit."}, {"verse": 20, "start": 157.38, "end": 160.52, "ta": "தீர்க்கதரிசனங்களை அற்பமாயெண்ணாதிருங்கள்.", "en": "Despise not prophesyings."}, {"verse": 21, "start": 160.52, "end": 165.58, "ta": "எல்லாவற்றையும் சோதித்துப்பார்த்து, நலமானதைப் பிடித்துக்கொள்ளுங்கள்.", "en": "Prove all things; hold fast that which is good."}, {"verse": 22, "start": 165.58, "end": 169.87, "ta": "பொல்லாங்காய்த் தோன்றுகிற எல்லாவற்றையும் விட்டு விலகுங்கள்.", "en": "Abstain from all appearance of evil."}, {"verse": 23, "start": 169.87, "end": 182.61, "ta": "சமாதானத்தின் தேவன் தாமே உங்களை முற்றிலும் பரிசுத்தமாக்குவாராக, உங்கள் ஆவி ஆத்துமா சரீரம்முழுவதும், நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்து வரும்போது குற்றமற்றதாயிருக்கும்படி காக்கப்படுவதாக.", "en": "And the very God of peace sanctify you wholly; and I pray God your whole spirit and soul and body be preserved blameless unto the coming of our Lord Jesus Christ."}, {"verse": 24, "start": 182.61, "end": 187.03, "ta": "உங்களை அழைக்கிறவர் உண்மையுள்ளவர், அவர் அப்படியே செய்வார்.", "en": "Faithful is he that calleth you, who also will do it."}, {"verse": 25, "start": 187.03, "end": 190.43, "ta": "சகோதரரே, எங்களுக்காக வேண்டிக்கொள்ளுங்கள்.", "en": "Brethren, pray for us."}, {"verse": 26, "start": 190.43, "end": 194.4, "ta": "சகோதரரெல்லாரையும் பரிசுத்த முத்தத்தோடே வாழ்த்துங்கள்.", "en": "Greet all the brethren with an holy kiss."}, {"verse": 27, "start": 194.4, "end": 203.43, "ta": "இந்த நிருபம் பரிசுத்தமான சகோதரர் யாவருக்கும் வாசிக்கப்படும்படி செய்யவேண்டுமென்று கர்த்தர்பேரில் ஆணையிட்டு உங்களுக்குச் சொல்லுகிறேன்.", "en": "I charge you by the Lord that this epistle be read unto all the holy brethren."}, {"verse": 28, "start": 203.43, "end": 209.64, "ta": "நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவினுடைய கிருபை உங்களுடனேகூட இருப்பதாக. ஆமென்.", "en": "The grace of our Lord Jesus Christ be with you. Amen."}]}}});
} else {
  window.BIBLE_CACHE = window.BIBLE_CACHE || {};
  window.BIBLE_CACHE['52'] = {"id": 52, "testament": "NT", "code": "1TH", "name_en": "1 Thessalonians", "name_ta": "1 தெசலோனிக்கேயர்", "category": "Pauline Epistles", "category_ta": "பவுலின் நிருபங்கள்", "total_chapters": 5, "chapters": {"1": {"chapter": 1, "duration": 133.95, "audio_url": "audio_nt/B13_01.mp3", "total_verses": 10, "verses": [{"verse": 1, "start": 4.8, "end": 23.12, "ta": "பவுலும், சில்வானும், தீமோத்தேயும், பிதாவாகிய தேவனுக்குள்ளும் கர்த்தராகிய இயேசுகிறிஸ்துவுக்குள்ளும் இருக்கிற தெசலோனிக்கேயர் சபைக்கு எழுதுகிறதாவது: நம்முடைய பிதாவாகிய தேவனாலும் கர்த்தராகிய இயேசுகிறிஸ்துவினாலும் உங்களுக்குக் கிருபையும் சமாதானமும் உண்டாவதாக.", "en": "Paul, and Silvanus, and Timotheus, unto the church of the Thessalonians which is in God the Father and in the Lord Jesus Christ: Grace be unto you, and peace, from God our Father, and the Lord Jesus Christ."}, {"verse": 2, "start": 23.12, "end": 40.77, "ta": "தேவனுக்குப் பிரியமான சகோதரரே, உங்கள் விசுவாசத்தின் கிரியையையும், உங்கள் அன்பின் பிரயாசத்தையும், நம்முடைய கர்த்தருடைய இயேசுகிறிஸ்துவின்மேலுள்ள உங்கள் நம்பிக்கையின் பொறுமையையும், நம்முடைய பிதாவாகிய தேவனுக்குமுன்பாக நாங்கள் இடைவிடாமல் நினைவுகூர்ந்து,", "en": "We give thanks to God always for you all, making mention of you in our prayers;"}, {"verse": 3, "start": 40.77, "end": 44.61, "ta": "நீங்கள் தெரிந்துகொள்ளப்பட்டவர்களென்று நாங்கள் அறிந்து,", "en": "Remembering without ceasing your work of faith, and labour of love, and patience of hope in our Lord Jesus Christ, in the sight of God and our Father;"}, {"verse": 4, "start": 44.61, "end": 53.64, "ta": "எங்கள் ஜெபங்களில் இடைவிடாமல் உங்களைக்குறித்து விண்ணப்பம்பண்ணி, உங்களெல்லாருக்காகவும் எப்பொழுதும் தேவனை ஸ்தோத்திரிக்கிறோம்.", "en": "Knowing, brethren beloved, your election of God."}, {"verse": 5, "start": 53.64, "end": 70.07, "ta": "எங்கள் சுவிசேஷம் உங்களிடத்தில் வசனத்தோடேமாத்திரமல்ல, வல்லமையோடும், பரிசுத்த ஆவியோடும், முழுநிச்சயத்தோடும் வந்தது; நாங்களும் உங்களுக்குள்ளே இருந்தபோது உங்கள்நிமித்தம் எப்படிப்பட்டவர்களாயிருந்தோமென்று அறிந்திருக்கிறீர்களே.", "en": "For our gospel came not unto you in word only, but also in power, and in the Holy Ghost, and in much assurance; as ye know what manner of men we were among you for your sake."}, {"verse": 6, "start": 70.07, "end": 79.98, "ta": "நீங்கள் மிகுந்த உபத்திரவத்திலே, பரிசுத்த ஆவியின் சந்தோஷத்தோடே, தοருவசனத்தை ஏற்றுக்கொண்டு, எங்களையும் கர்த்தரையும் பின்பற்றுகிறவர்களாகி,", "en": "And ye became followers of us, and of the Lord, having received the word in much affliction, with joy of the Holy Ghost:"}, {"verse": 7, "start": 79.98, "end": 86.31, "ta": "இவ்விதமாய் மக்கெதோனியாவிலும் அகாயாவிலுமுள்ள விசுவாசிகள் யாவருக்கும் மாதிரிகளானீர்கள்.", "en": "So that ye were ensamples to all that believe in Macedonia and Achaia."}, {"verse": 8, "start": 86.31, "end": 102.0, "ta": "எப்படியெனில், உங்களிடத்திலிருந்து கர்த்தருடைய வசனம் மக்கெதோனியாவிலும் அகாயாவிலும் தொனித்ததுமல்லாமல், நாங்கள் அதைக்குறித்து ஒன்றும் சொல்லவேண்டியதாயிராதபடிக்கு, தேவனைப்பற்றின உங்கள் விசுவாசம் எங்கும் பிரசித்தமாயிற்று.", "en": "For from you sounded out the word of the Lord not only in Macedonia and Achaia, but also in every place your faith to God-ward is spread abroad; so that we need not to speak any thing."}, {"verse": 9, "start": 102.0, "end": 116.69, "ta": "ஏனெனில், அவர்கள்தாமே எங்களைக்குறித்து, உங்களிடத்தில் நாங்கள் அடைந்த பிரவேசம் இன்னதென்பதையும், ஜீவனுள்ள மெய்யான தேவனுக்கு ஊழியஞ்செய்வதற்கு, நீங்கள் விக்கிரகங்களை விட்டு தேவனிடத்திற்கு மனந்திரும்பினதையும்,", "en": "For they themselves shew of us what manner of entering in we had unto you, and how ye turned to God from idols to serve the living and true God;"}, {"verse": 10, "start": 116.69, "end": 132.45, "ta": "அவர் மரித்தோரிலிருந்தெழுப்பினவரும், இனிவரும் கோபாக்கினையினின்று நம்மை நீங்கலாக்கி இரட்சிக்கிறவருமாயிருக்கிற அவருடைய குமாரனாகிய இயேசு பரலோகத்திலிருந்து வருவதை நீங்கள் எதிர்பார்த்துக்கொண்டிருக்கிறதையும், அறிவிக்கிறார்களே.", "en": "And to wait for his Son from heaven, whom he raised from the dead, even Jesus, which delivered us from the wrath to come."}]}, "2": {"chapter": 2, "duration": 239.5, "audio_url": "audio_nt/B13_02.mp3", "total_verses": 20, "verses": [{"verse": 1, "start": 3.8, "end": 11.13, "ta": "சகோதரரே, நாங்கள் உங்களிடத்தில் பிரவேசித்தது வீணாயிருக்கவில்லையென்று நீங்களே அறிந்திருக்கிறீர்கள்.", "en": "For yourselves, brethren, know our entrance in unto you, that it was not in vain:"}, {"verse": 2, "start": 11.13, "end": 26.45, "ta": "உங்களுக்குத் தெரிந்திருக்கிறபடி, முன்னே பிலிப்பிபட்டணத்திலே நாங்கள் பாடுபட்டு நிந்தையடைந்திருந்தும், வெகு போராட்டத்தோடே தேவனுடைய சுவிசேஷத்தை உங்களுக்குச் சொல்லும்படி, நம்முடைய தேவனுக்குள் தைரியங்கொண்டிருந்தோம்.", "en": "But even after that we had suffered before, and were shamefully entreated, as ye know, at Philippi, we were bold in our God to speak unto you the gospel of God with much contention."}, {"verse": 3, "start": 26.45, "end": 33.24, "ta": "எங்கள் போதகம் வஞ்சகத்தினாலும் துராசையினாலும் உண்டாகவில்லை, அது கபடமுள்ளதாயுமிருக்கவில்லை.", "en": "For our exhortation was not of deceit, nor of uncleanness, nor in guile:"}, {"verse": 4, "start": 33.24, "end": 46.42, "ta": "சுவிசேஷத்தை எங்களிடத்தில் ஒப்புவிக்கத்தக்கதாய், தேவன் எங்களை உத்தமரென்றெண்ணினபடியே, நாங்கள் மனுஷருக்கு அல்ல, எங்கள் இருதயங்களைச் சோதித்தறிகிற தேவனுக்கே பிரியமுண்டாகப் பேசுகிறோம்.", "en": "But as we were allowed of God to be put in trust with the gospel, even so we speak; not as pleasing men, but God, which trieth our hearts."}, {"verse": 5, "start": 46.42, "end": 57.38, "ta": "உங்களுக்குத் தெரிந்திருக்கிறபடி, நாங்கள் ஒருக்காலும் இச்சகமான வசனங்களைச் சொல்லவுமில்லை, பொருளாசையுள்ளவர்களாய் மாயம்பண்ணவுமில்லை; தேவனே சாட்சி.", "en": "For neither at any time used we flattering words, as ye know, nor a cloke of covetousness; God is witness:"}, {"verse": 6, "start": 57.38, "end": 69.41, "ta": "நாங்கள் கிறிஸ்துவின் அப்போஸ்தலராக உங்களுக்குப் பாரமாயிருக்கக்கூடியவர்களானாலும், உங்களிடத்திலாவது, மற்றவர்களிடத்திலாவது, மனுஷரால் வரும் மகிமையை நாங்கள் தேடவில்லை.", "en": "Nor of men sought we glory, neither of you, nor yet of others, when we might have been burdensome, as the apostles of Christ."}, {"verse": 7, "start": 69.41, "end": 76.6, "ta": "உங்களிடத்தில் பட்சமாய் நடந்துகொண்டோம்; பால் கொடுக்கிற தாயானவள் தன் பிள்ளைகளைக் காப்பாற்றுகிறதுபோல,", "en": "But we were gentle among you, even as a nurse cherisheth her children:"}, {"verse": 8, "start": 76.6, "end": 90.58, "ta": "நாங்கள் உங்கள்மேல் வாஞ்சையாயிருந்து, தேவனுடைய சுவிசேஷத்தை உங்களுக்குக் கொடுத்ததுமல்லாமல், நீங்கள் எங்களுக்குப் பிரியமானவர்களானபடியினாலே, எங்கள் ஜீவனையும் உங்களுக்குக் கொடுக்க மனதாயிருந்தோம்.", "en": "So being affectionately desirous of you, we were willing to have imparted unto you, not the gospel of God only, but also our own souls, because ye were dear unto us."}, {"verse": 9, "start": 90.58, "end": 105.51, "ta": "சகோதரரே, நாங்கள் பட்ட பிரயாசமும் வருத்தமும் உங்களுக்கு ஞாபகமாயிருக்கும்; உங்களில் ஒருவனுக்கும் பாரமாயிராதபடிக்கு, இரவும் பகலும் நாங்கள் வேலைசெய்து, தேவனுடைய சுவிசேஷத்தை உங்களிடத்தில் பிரசங்சித்தோம்.", "en": "For ye remember, brethren, our labour and travail: for labouring night and day, because we would not be chargeable unto any of you, we preached unto you the gospel of God."}, {"verse": 10, "start": 105.51, "end": 115.39, "ta": "விசுவாசிகளாகிய உங்களுக்குள்ளே நாங்கள் எவ்வளவு பரிசுத்தமும் நீதியும் பிழையின்மையுமாய் நடந்தோமென்பதற்கு நீங்களும் சாட்சி, தேவனும் சாட்சி.", "en": "Ye are witnesses, and God also , how holily and justly and unblameably we behaved ourselves among you that believe:"}, {"verse": 11, "start": 115.39, "end": 122.98, "ta": "மேலும், தம்முடைய ராஜ்யத்திற்கும் மகிமைக்கும் உங்களை அழைத்த தேவனுக்கு நீங்கள் பாத்திரராய் நடக்கவேண்டுமென்று,", "en": "As ye know how we exhorted and comforted and charged every one of you, as a father doth his children,"}, {"verse": 12, "start": 122.98, "end": 133.27, "ta": "தகப்பன் தன் பிள்ளைகளுக்குச் சொல்லுகிறதுபோல, நாங்கள் உங்களில் ஒவ்வொருவனுக்கும் புத்தியும் தேறுதலும் எச்சரிப்பும் சொன்னதை அறிந்திருக்கிறீர்கள்.", "en": "That ye would walk worthy of God, who hath called you unto his kingdom and glory."}, {"verse": 13, "start": 133.27, "end": 153.3, "ta": "ஆகையால், நீங்கள் தேவவசனத்தை எங்களாலே கேள்விப்பட்டு ஏற்றுக்கொண்டபோது, அதை மனுஷர் வசனமாக ஏற்றுக்கொள்ளாமல், தேவவசனமாகவே ஏற்றுக்கொண்டதினாலே நாங்கள் இடைவிடாமல் தேவனுக்கு ஸ்தோத்திரஞ்செலுத்துகிறோம்; அது மெய்யாகவே தேவவசனந்தான், விசுவாசிக்கிற உங்களுக்குள்ளே அது பெலனும் செய்கிறது.", "en": "For this cause also thank we God without ceasing, because, when ye received the word of God which ye heard of us, ye received it not as the word of men, but as it is in truth, the word of God, which effectually worketh also in you that believe."}, {"verse": 14, "start": 153.3, "end": 168.56, "ta": "எப்படியெனில், சகோதரரே, யூதேயா தேசத்தில் கிறிஸ்து இயேசுவுக்குள்ளான தேவனுடைய சபைகளை நீங்கள் பின்பற்றினவர்களாகி, அவர்கள் யூதராலே எப்படிப் பாடுபட்டார்களோ, அப்படியே நீங்களும் உங்கள் சுய ஜனங்களாலே பாடுபட்டீர்கள்.", "en": "For ye, brethren, became followers of the churches of God which in Judaea are in Christ Jesus: for ye also have suffered like things of your own countrymen, even as they have of the Jews:"}, {"verse": 15, "start": 168.56, "end": 181.8, "ta": "அந்த யூதர்கள் கர்த்தராகிய இயேசுவையும், தங்கள் தீர்க்கதரிசிகளையும் கொலைசெய்தவர்களும், எங்களைத் துன்பப்படுத்தினவர்களும், தேவனுக்கேற்காதவர்களும், மனுஷர் யாவருக்கும் விரோதிகளுமாயிருந்து,", "en": "Who both killed the Lord Jesus, and their own prophets, and have persecuted us; and they please not God, and are contrary to all men:"}, {"verse": 16, "start": 181.8, "end": 196.32, "ta": "புறஜாதியார் இரட்சிக்கப்படுவதற்கு நாங்கள் அவர்களோடே பேசாதபடிக்குத் தடைபண்ணுகிறார்கள்; இவ்விதமாய் எக்காலத்திலும் தங்கள் பாவங்களை நிறைவாக்குகிறார்கள்; அவர்கள்மேல் கோபாக்கினை பூரணமாய் வந்திருக்கிறது.", "en": "Forbidding us to speak to the Gentiles that they might be saved, to fill up their sins alway: for the wrath is come upon them to the uttermost."}, {"verse": 17, "start": 196.32, "end": 210.78, "ta": "சகோதரரே, நாங்கள் இருதயத்தின்படி உங்களோடிருந்து, சரீரத்தின்படி கொஞ்சக்காலம் உங்களைவிட்டுப் பிரிந்திருந்தபடியினாலே, உங்கள் முகத்தைப்பார்க்கவேண்டுமென்று மிகுந்த ஆசையோடே அதிகமாய்ப் பிரயத்தனம்பண்ணினோம்.", "en": "But we, brethren, being taken from you for a short time in presence, not in heart, endeavoured the more abundantly to see your face with great desire."}, {"verse": 18, "start": 210.78, "end": 220.66, "ta": "ஆகையால், நாங்கள் உங்களிடத்தில்வர இரண்டொருதரம் மனதாயிருந்தோம், பவுலாகிய நானே வர மனதாயிருந்தேன்; சாத்தானோ எங்களைத் தடைபண்ணினான்.", "en": "Wherefore we would have come unto you, even I Paul, once and again; but Satan hindered us."}, {"verse": 19, "start": 220.66, "end": 233.7, "ta": "எங்களுக்கு நம்பிக்கையும் சந்தோஷமும் மகிழ்ச்சியின் கிரீடமுமாயிருப்பவர்கள் யார்? நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்து வரும்போது அவருடைய சந்நிதானத்திலே நீங்களல்லவா அப்படியிருப்பீர்கள்;", "en": "For what is our hope, or joy, or crown of rejoicing? Are not even ye in the presence of our Lord Jesus Christ at his coming?"}, {"verse": 20, "start": 233.7, "end": 238.0, "ta": "நீங்களே எங்களுக்கு மகிமையும் சந்தோஷமுமாயிருக்கிறீர்கள்.", "en": "For ye are our glory and joy."}]}, "3": {"chapter": 3, "duration": 149.32, "audio_url": "audio_nt/B13_03.mp3", "total_verses": 13, "verses": [{"verse": 1, "start": 3.8, "end": 11.41, "ta": "ஆகையால், நாங்கள் இனிப் பொறுத்திருக்கக்கூடாமல், அத்தேனே பட்டணத்தில் தனித்துவிடப்படுகிறது நன்மையென்று நினைத்து,", "en": "Wherefore when we could no longer forbear, we thought it good to be left at Athens alone;"}, {"verse": 2, "start": 11.41, "end": 28.37, "ta": "இந்த உபத்திரவங்களினாலே ஒருவனும் அசைக்கப்படாதபடிக்கு உங்களைத் திடப்படுத்தவும், உங்கள் விசுவாசத்தைப்பற்றி உங்களுக்குப் புத்திசொல்லவும், நம்முடைய சகோதரனும் தேவ ஊழியக்காரனும் கிறிஸ்துவின் சுவிசேஷத்தில் எங்கள் உடன்வேலையாளுமாகிய தீமோத்தேயுவை அனுப்பினோம்.", "en": "And sent Timotheus, our brother, and minister of God, and our fellowlabourer in the gospel of Christ, to establish you, and to comfort you concerning your faith:"}, {"verse": 3, "start": 28.37, "end": 35.4, "ta": "இப்படிப்பட்ட உபத்திரவங்களைச் சகிக்க நாம் நியமிக்கப்பட்டிருக்கிறோமென்று நீங்கள் அறிந்திருக்கிறீர்களே.", "en": "That no man should be moved by these afflictions: for yourselves know that we are appointed thereunto."}, {"verse": 4, "start": 35.4, "end": 45.59, "ta": "நமக்கு உபத்திரவம் வருமென்று நாங்கள் உங்களிடத்திலிருந்தபோது, உங்களுக்கு முன்னறிவித்தோம்; அப்படியே வந்து நேரிட்டதென்றும் அறிந்திருக்கிறீர்கள்.", "en": "For verily, when we were with you, we told you before that we should suffer tribulation; even as it came to pass, and ye know."}, {"verse": 5, "start": 45.59, "end": 59.01, "ta": "ஆகையால், நான் இனிப் பொறுத்திருக்கக்கூடாமல், எங்கள் வேலை வீணாய்ப் போகத்தக்கதாகச் சோதனைக்காரன் உங்களைச் சோதனைக்குட்படுத்தினதுண்டோவென்று, உங்கள் விசுவாசத்தை அறியும்படிக்கு, அவனை அனுப்பினேன்.", "en": "For this cause, when I could no longer forbear, I sent to know your faith, lest by some means the tempter have tempted you, and our labour be in vain."}, {"verse": 6, "start": 59.01, "end": 79.58, "ta": "இப்பொழுது தீமோத்தேயு உங்களிடத்திலிருந்து எங்களிடத்தில் வந்து, உங்கள் விசுவாசத்தையும் அன்பையும் குறித்தும், நீங்கள் எப்பொழுதும் எங்களைப் பட்சமாய் நினைத்துக்கொண்டு, நாங்கள் உங்களைக் காண வாஞ்சையாயிருக்கிறதுபோல நீங்களும் எங்களைக் காண வாஞ்சையாயிருக்கிறீர்களென்பதைக்குறித்தும், எங்களுக்கு நற்செய்திசொன்னதினாலே,", "en": "But now when Timotheus came from you unto us, and brought us good tidings of your faith and charity, and that ye have good remembrance of us always, desiring greatly to see us, as we also to see you:"}, {"verse": 7, "start": 79.58, "end": 87.9, "ta": "சகோதரரே, எங்களுக்கு நேரிட்ட எல்லா இக்கட்டிலும் உபத்திரவத்திலும் உங்கள் விசுவாசத்தினாலே உங்களை குறித்து ஆறுதலடைந்தோம்.", "en": "Therefore, brethren, we were comforted over you in all our affliction and distress by your faith:"}, {"verse": 8, "start": 87.9, "end": 92.68, "ta": "நீங்கள் கர்த்தருக்குள் நிலைத்திருந்தால் நாங்கள் பிழைத்திருப்போம்.", "en": "For now we live, if ye stand fast in the Lord."}, {"verse": 9, "start": 92.68, "end": 103.58, "ta": "மேலும், நம்முடைய தேவனுக்கு முன்பாக நாங்கள் உங்களைக்குறித்து அடைந்திருக்கிற மிகுந்த சந்தோஷத்திற்காக, நாங்கள் தேவனுக்கு எவ்விதமாய் ஸ்தோத்திரம் செலுத்துவோம்?", "en": "For what thanks can we render to God again for you, for all the joy wherewith we joy for your sakes before our God;"}, {"verse": 10, "start": 103.58, "end": 112.15, "ta": "உங்கள் முகத்தைக் கண்டு, உங்கள் விசுவாசத்தின் குறைவுகளை நிறைவாக்கும்பொருட்டு, இரவும் பகலும் மிகவும் வேண்டிக்கொள்கிறோமே.", "en": "Night and day praying exceedingly that we might see your face, and might perfect that which is lacking in your faith?"}, {"verse": 11, "start": 112.15, "end": 119.83, "ta": "நம்முடைய பிதாவாகிய தேவனும் நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவும் உங்களிடத்திற்கு எங்களை நேராக வழிநடத்துவாராக.", "en": "Now God himself and our Father, and our Lord Jesus Christ, direct our way unto you."}, {"verse": 12, "start": 119.83, "end": 132.92, "ta": "நாங்கள் உங்களிடத்தில் வைத்திருக்கிற அன்புக்கொப்பாய், நீங்களும் ஒருவரிடத்தில் ஒருவர் வைக்கும் அன்பிலும் மற்றெல்லா மனுஷரிடத்தில் வைக்கும் அன்பிலும் கர்த்தர் உங்களைப் பெருகவும் நிலைத்தோங்கவும் செய்து,", "en": "And the Lord make you to increase and abound in love one toward another, and toward all men , even as we do toward you:"}, {"verse": 13, "start": 132.92, "end": 147.82, "ta": "இவ்விதமாய் நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்து தமது பரிசுத்தவான்கள் அனைவரோடுங்கூட வரும்போது, நீங்கள் நம்முடைய பிதாவாகிய தேவனுக்கு முன்பாகப் பிழையற்ற பரிசுத்தமுள்ளவர்களாயிருக்கும்படி உங்கள் இருதயங்களை ஸ்திரப்படுத்துவாராக.", "en": "To the end he may stablish your hearts unblameable in holiness before God, even our Father, at the coming of our Lord Jesus Christ with all his saints."}]}, "4": {"chapter": 4, "duration": 173.77, "audio_url": "audio_nt/B13_04.mp3", "total_verses": 18, "verses": [{"verse": 1, "start": 3.8, "end": 20.82, "ta": "அன்றியும், சகோதரரே, நீங்கள் இன்னின்ன பிரகாரமாய் நடக்கவும், தேவனுக்குப் பிரியமாயிருக்கவும் வேண்டுமென்று, நீங்கள் எங்களால் கேட்டு ஏற்றுக்கொண்டபடியே, அதிகமதிகமாய்த் தேறும்படிக்கு, கர்த்தராகிய இயேசுவுக்குள் உங்களை வேண்டிக்கொண்டு புத்திசொல்லுகிறோம்.", "en": "Furthermore then we beseech you, brethren, and exhort you by the Lord Jesus, that as ye have received of us how ye ought to walk and to please God, so ye would abound more and more."}, {"verse": 2, "start": 20.82, "end": 26.66, "ta": "கர்த்தராகிய இயேசுவினாலே நாங்கள் உங்களுக்குக் கொடுத்த கட்டளைகளை அறிந்திருக்கிறீர்களே.", "en": "For ye know what commandments we gave you by the Lord Jesus."}, {"verse": 3, "start": 26.66, "end": 35.4, "ta": "நீங்கள் பரிசுத்தமுள்ளவர்களாகவேண்டுமென்பதே தேவனுடைய சித்தமாயிருக்கிறது. அந்தப்படி, நீங்கள் வேசிமார்க்கத்துக்கு விலகியிருந்து,", "en": "For this is the will of God, even your sanctification, that ye should abstain from fornication:"}, {"verse": 4, "start": 35.4, "end": 38.79, "ta": "தேவனை அறியாத அஞ்ஞானிகளைப்போல மோக இச்சைக்குட்படாமல்,", "en": "That every one of you should know how to possess his vessel in sanctification and honour;"}, {"verse": 5, "start": 38.79, "end": 44.32, "ta": "உங்களில் அவனவன் தன்தன் சரீரபாண்டத்தைப் பரிசுத்தமாயும் கனமாயும் ஆண்டுகொள்ளும்படி அறிந்து:", "en": "Not in the lust of concupiscence, even as the Gentiles which know not God:"}, {"verse": 6, "start": 44.32, "end": 59.96, "ta": "இந்த விஷயத்தில் ஒருவனும் மீறாமலும் தன் சகோதரனை வஞ்சியாமலும் இருக்கவேண்டும்; முன்னமே நாங்கள் உங்களுக்குச் சொல்லி, சாட்சியாக எச்சரித்தபடியே இப்படிப்பட்ட விஷயங்களெல்லாவற்றையுங்குறித்துக் கர்த்தர் நீதியைச் சரிக்கட்டுகிறவராயிருக்கிறார்.", "en": "That no man go beyond and defraud his brother in any matter: because that the Lord is the avenger of all such, as we also have forewarned you and testified."}, {"verse": 7, "start": 59.96, "end": 64.54, "ta": "தேவன் நம்மை அசுத்தத்திற்கல்ல பரிசுத்தத்திற்கே அழைத்திருக்கிறார்.", "en": "For God hath not called us unto uncleanness, but unto holiness."}, {"verse": 8, "start": 64.54, "end": 71.58, "ta": "ஆகையால் அசட்டைபண்ணுகிறவன் மனுஷரை அல்ல தமது பரிசுத்த ஆவியை நமக்குத் தந்தருளின தேவனையே அசட்டைபண்ணுகிறான்.", "en": "He therefore that despiseth, despiseth not man, but God, who hath also given unto us his holy Spirit."}, {"verse": 9, "start": 71.58, "end": 81.88, "ta": "சகோதர சிநேகத்தைக்குறித்து நான் உங்களுக்கு எழுதவேண்டுவதில்லை; நீங்கள் ஒருவரிலொருவர் அன்பாயிருக்கும்படிக்கு தேவனால் போதிக்கப்பட்டவர்களாயிருக்கிறீர்களே.", "en": "But as touching brotherly love ye need not that I write unto you: for ye yourselves are taught of God to love one another."}, {"verse": 10, "start": 81.88, "end": 91.68, "ta": "அந்தப்படி நீங்கள் மக்கெதோனியா நாடெங்குமுள்ள சகோதரரெல்லாருக்கும் செய்துவருகிறீர்கள். சகோதரரே, அன்பிலே நீங்கள் இன்னும் அதிகமாய்ப் பெருகவும்;", "en": "And indeed ye do it toward all the brethren which are in all Macedonia: but we beseech you, brethren, that ye increase more and more;"}, {"verse": 11, "start": 91.68, "end": 98.4, "ta": "புறம்பேயிருக்கிறவர்களைப்பற்றி யோக்கியமாய் நடந்து, ஒன்றிலும் உங்களுக்குக் குறைவில்லாதிருக்கும்படிக்கு,", "en": "And that ye study to be quiet, and to do your own business, and to work with your own hands, as we commanded you;"}, {"verse": 12, "start": 98.4, "end": 112.03, "ta": "நாங்கள் உங்களுக்குக் கட்டளையிட்டபடியே, அமைதலுள்ளவர்களாயிருக்கும்படி நாடவும், உங்கள் சொந்த அலுவல்களைப் பார்க்கவும், உங்கள் சொந்தக் கைகளினாலே வேலைசெய்யவும் வேண்டுமென்று உங்களுக்குப் புத்திசொல்லுகிறோம்.", "en": "That ye may walk honestly toward them that are without, and that ye may have lack of nothing."}, {"verse": 13, "start": 112.03, "end": 122.14, "ta": "அன்றியும், சகோதரரே, நித்திரையடைந்தவர்களினிமித்தம் நீங்கள் நம்பிக்கையற்றவர்களான மற்றவர்களைப் போலத் துக்கித்து, அறிவில்லாதிருக்க எனக்கு மனதில்லை.", "en": "But I would not have you to be ignorant, brethren, concerning them which are asleep, that ye sorrow not, even as others which have no hope."}, {"verse": 14, "start": 122.14, "end": 132.19, "ta": "இயேசுவானவர் மரித்து பின்பு எழுந்திருந்தாரென்று விசுவாசிக்கிறோமே; அப்படியே இயேசுவுக்குள் நித்திரையடைந்தவர்களையும் தேவன் அவரோடேகூடக் கொண்டுவருவார்.", "en": "For if we believe that Jesus died and rose again, even so them also which sleep in Jesus will God bring with him."}, {"verse": 15, "start": 132.19, "end": 142.94, "ta": "கர்த்தருடைய வார்த்தையை முன்னிட்டு நாங்கள் உங்களுக்குச் சொல்லுகிறதாவது: கர்த்தருடைய வருகைமட்டும் உயிரோடிருக்கும் நாம் நித்திரையடைந்தவர்களுக்கு முந்திக்கொள்வதில்லை.", "en": "For this we say unto you by the word of the Lord, that we which are alive and remain unto the coming of the Lord shall not prevent them which are asleep."}, {"verse": 16, "start": 142.94, "end": 156.06, "ta": "ஏனெனில், கர்த்தர் தாமே ஆரவாத்தோடும், பிரதான தூதனுடைய சத்தத்தோடும், தேவ எக்காளத்தோடும் வானத்திலிருந்து இறங்கிவருவார்; அப்பொழுது கிறிஸ்துவுக்குள் மரித்தவர்கள் முதலாவது எழுந்திருப்பார்கள்.", "en": "For the Lord himself shall descend from heaven with a shout, with the voice of the archangel, and with the trump of God: and the dead in Christ shall rise first:"}, {"verse": 17, "start": 156.06, "end": 167.5, "ta": "பின்பு உயிரோடிருக்கும் நாமும் கர்த்தருக்கு எதிர்கொண்டுபோக மேகங்கள்மேல், அவர்களோடேகூட ஆகாயத்தில் எடுத்துக்கொள்ளப்பட்டு, இவ்விதமாய் எப்பொழுதும் கர்த்தருடனேகூட இருப்போம்.", "en": "Then we which are alive and remain shall be caught up together with them in the clouds, to meet the Lord in the air: and so shall we ever be with the Lord."}, {"verse": 18, "start": 167.5, "end": 172.27, "ta": "ஆகையால், இந்த வார்த்தைகளினாலே நீங்கள் ஒருவரையொருவர் தேற்றுங்கள்.", "en": "Wherefore comfort one another with these words."}]}, "5": {"chapter": 5, "duration": 211.14, "audio_url": "audio_nt/B13_05.mp3", "total_verses": 28, "verses": [{"verse": 1, "start": 3.8, "end": 9.88, "ta": "சகோதரரே இவைகள் நடக்குங்காலங்களையும் சமயங்களையுங்குறித்து உங்களுக்கு எழுதவேண்டுவதில்லை.", "en": "But of the times and the seasons, brethren, ye have no need that I write unto you."}, {"verse": 2, "start": 9.88, "end": 16.54, "ta": "இரவிலே திருடன் வருகிறவிதமாய்க் கர்த்தருடைய நாள் வருமென்று நீங்களே நன்றாய் அறிந்திருக்கிறீர்கள்.", "en": "For yourselves know perfectly that the day of the Lord so cometh as a thief in the night."}, {"verse": 3, "start": 16.54, "end": 27.82, "ta": "சமாதானமும் சவுக்கியமும் உண்டென்று அவர்கள் சொல்லும்போது, கர்ப்பவதியானவளுக்கு வேதனை வருகிறதுபோல, அழிவு சடிதியாய் அவர்கள்மேல் வரும்; அவர்கள் தப்பிப்போவதில்லை.", "en": "For when they shall say, Peace and safety; then sudden destruction cometh upon them, as travail upon a woman with child; and they shall not escape."}, {"verse": 4, "start": 27.82, "end": 35.31, "ta": "சகோதரரே, அந்த நாள் திருடனைப்போல உங்களைப் பிடித்துக்கொள்ளத்தக்கதாக நீங்கள் அந்தகாரத்திலிருக்கிறவர்களல்லவே.", "en": "But ye, brethren, are not in darkness, that that day should overtake you as a thief."}, {"verse": 5, "start": 35.31, "end": 44.53, "ta": "நீங்களெல்லாரும் வெளிச்சத்தின் பிள்ளைகளும், பகலின் பிள்ளைகளுமாயிருக்கிறீர்கள்; நாம் இயேசுவுக்கும் இருளுக்கும் உள்ளானவர்களல்லவே.", "en": "Ye are all the children of light, and the children of the day: we are not of the night, nor of darkness."}, {"verse": 6, "start": 44.53, "end": 51.71, "ta": "ஆகையால், மற்றவர்கள் தூங்குகிறதுபோல நாம் தூங்காமல், விழித்துக்கொண்டு தெளிந்தவர்களாயிருக்கக்கடவோம்.", "en": "Therefore let us not sleep, as do others; but let us watch and be sober."}, {"verse": 7, "start": 51.71, "end": 58.88, "ta": "தூங்குகிறவர்கள் இராத்திரியிலே தூங்குவார்கள்; வெறிகொள்ளுகிறவர்கள் இராத்திரியிலே வெறிகொள்ளுவார்கள்.", "en": "For they that sleep sleep in the night; and they that be drunken are drunken in the night."}, {"verse": 8, "start": 58.88, "end": 70.6, "ta": "பகலுக்குரியவர்களாகிய நாமோ தெளிந்தவர்களாயிருந்து, விசுவாசம் அன்பு என்னும் மார்க்கவசத்தையும், இரட்சிப்பின் நம்பிக்கையென்னும் தலைச்சீராவையும் தரித்துக்கொண்டிருக்கக்கடவாம்.", "en": "But let us, who are of the day, be sober, putting on the breastplate of faith and love; and for an helmet, the hope of salvation."}, {"verse": 9, "start": 70.6, "end": 79.24, "ta": "தேவன் நம்மைக் கோபாக்கினைக்கென்று நியமிக்காமல், நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துமூலமாய் இரட்சிப்படைவதற்கென்று நியமித்தார்.", "en": "For God hath not appointed us to wrath, but to obtain salvation by our Lord Jesus Christ,"}, {"verse": 10, "start": 79.24, "end": 88.21, "ta": "நாம் விழித்திருப்பவர்களானாலும் நித்திரையடைந்தவர்களானாலும், தம்முடனேகூட நாம் ஏகமாய்ப் பிழைத்திருக்கும்படி அவர் நமக்காக மரித்தாரே.", "en": "Who died for us, that, whether we wake or sleep, we should live together with him."}, {"verse": 11, "start": 88.21, "end": 96.34, "ta": "ஆகையால் நீங்கள் செய்துவருகிறபடியே, ஒருவரையொருவர் தேற்றி, ஒருவருக்கொருவர் பக்திவிருத்தி உண்டாகும்படி செய்யுங்கள்.", "en": "Wherefore comfort yourselves together, and edify one another, even as also ye do."}, {"verse": 12, "start": 96.34, "end": 107.1, "ta": "அன்றியும், சகோதரரே, உங்களுக்குள்ளே பிரயாசப்பட்டு, கர்த்தருக்குள் உங்களை விசாரணைசெய்கிறவர்களாயிருந்து, எங்களுக்குப் புத்திசொல்லுகிறவர்களை நீங்கள் மதித்து,", "en": "And we beseech you, brethren, to know them which labour among you, and are over you in the Lord, and admonish you;"}, {"verse": 13, "start": 107.1, "end": 116.84, "ta": "அவர்களுடைய கிரியையினிமித்தம் அவர்களை மிகவும் அன்பாய் எண்ணிக்கொள்ளும்படி உங்களை வேண்டிக்கொள்ளுகிறோம். உங்களுக்குள்ளே சமாதானமாயிருங்கள்.", "en": "And to esteem them very highly in love for their work’s sake. And be at peace among yourselves."}, {"verse": 14, "start": 116.84, "end": 131.25, "ta": "மேலும், சகோதரரே, நாங்கள் உங்களுக்குப் போதிக்கிறதென்னவென்றால், ஒழுங்கில்லாதவர்களுக்குப் புத்திசொல்லுங்கள், திடனற்றவர்களைத் தேற்றுங்கள், பலவீனரைத் தாங்குங்கள், எல்லாரிடத்திலும் நீடிய சாந்தமாயிருங்கள்.", "en": "Now we exhort you, brethren, warn them that are unruly, comfort the feebleminded, support the weak, be patient toward all men ."}, {"verse": 15, "start": 131.25, "end": 140.98, "ta": "ஒருவனும் மற்றொருவன் செய்யும் தீமைக்குத் தீமைசெய்யாதபடி பாருங்கள்; உங்களுக்குள்ளும் மற்ற யாவருக்குள்ளும் எப்பொழுதும் நன்மைசெய்ய நாடுங்கள்.", "en": "See that none render evil for evil unto any man ; but ever follow that which is good, both among yourselves, and to all men ."}, {"verse": 16, "start": 140.98, "end": 143.48, "ta": "எப்பொழுதும் சந்தோஷமாயிருங்கள்.", "en": "Rejoice evermore."}, {"verse": 17, "start": 143.48, "end": 145.79, "ta": "இடைவிடாமல் ஜெபம்பண்ணுங்கள்.", "en": "Pray without ceasing."}, {"verse": 18, "start": 145.79, "end": 154.95, "ta": "எல்லாவற்றிலேயும் ஸ்தோத்திரஞ்செய்யுங்கள்; அப்படிச் செய்வதே கிறிஸ்து இயேசுவுக்குள் உங்களைக்குறித்துத் தேவனுடைய சித்தமாயிருக்கிறது.", "en": "In every thing give thanks: for this is the will of God in Christ Jesus concerning you."}, {"verse": 19, "start": 154.95, "end": 157.38, "ta": "ஆவியை அவித்துப்போடாதிருங்கள்.", "en": "Quench not the Spirit."}, {"verse": 20, "start": 157.38, "end": 160.52, "ta": "தீர்க்கதரிசனங்களை அற்பமாயெண்ணாதிருங்கள்.", "en": "Despise not prophesyings."}, {"verse": 21, "start": 160.52, "end": 165.58, "ta": "எல்லாவற்றையும் சோதித்துப்பார்த்து, நலமானதைப் பிடித்துக்கொள்ளுங்கள்.", "en": "Prove all things; hold fast that which is good."}, {"verse": 22, "start": 165.58, "end": 169.87, "ta": "பொல்லாங்காய்த் தோன்றுகிற எல்லாவற்றையும் விட்டு விலகுங்கள்.", "en": "Abstain from all appearance of evil."}, {"verse": 23, "start": 169.87, "end": 182.61, "ta": "சமாதானத்தின் தேவன் தாமே உங்களை முற்றிலும் பரிசுத்தமாக்குவாராக, உங்கள் ஆவி ஆத்துமா சரீரம்முழுவதும், நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்து வரும்போது குற்றமற்றதாயிருக்கும்படி காக்கப்படுவதாக.", "en": "And the very God of peace sanctify you wholly; and I pray God your whole spirit and soul and body be preserved blameless unto the coming of our Lord Jesus Christ."}, {"verse": 24, "start": 182.61, "end": 187.03, "ta": "உங்களை அழைக்கிறவர் உண்மையுள்ளவர், அவர் அப்படியே செய்வார்.", "en": "Faithful is he that calleth you, who also will do it."}, {"verse": 25, "start": 187.03, "end": 190.43, "ta": "சகோதரரே, எங்களுக்காக வேண்டிக்கொள்ளுங்கள்.", "en": "Brethren, pray for us."}, {"verse": 26, "start": 190.43, "end": 194.4, "ta": "சகோதரரெல்லாரையும் பரிசுத்த முத்தத்தோடே வாழ்த்துங்கள்.", "en": "Greet all the brethren with an holy kiss."}, {"verse": 27, "start": 194.4, "end": 203.43, "ta": "இந்த நிருபம் பரிசுத்தமான சகோதரர் யாவருக்கும் வாசிக்கப்படும்படி செய்யவேண்டுமென்று கர்த்தர்பேரில் ஆணையிட்டு உங்களுக்குச் சொல்லுகிறேன்.", "en": "I charge you by the Lord that this epistle be read unto all the holy brethren."}, {"verse": 28, "start": 203.43, "end": 209.64, "ta": "நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவினுடைய கிருபை உங்களுடனேகூட இருப்பதாக. ஆமென்.", "en": "The grace of our Lord Jesus Christ be with you. Amen."}]}}};
}
